"""Original scenes and bounded stroke-order interaction for primary Chinese.

Illustrations express the teaching context. Stroke paths are authored geometry,
not an image of textbook artwork or a font split mistaken for stroke order.
"""
from html import escape

from content import textbook_activity_templates as t
from content.chinese_reading_activity import child


def posed_child(x, y, color, scale, arm_path, speaking=False):
    person = child(x, y, color, scale, speaking)
    person = person.replace('M69 132 53 151m62-19 16 19', arm_path)
    return person.replace('</g>', '<path d="M74 173v39m37-39v39" stroke="'+color+'" stroke-width="12"/><path d="M68 215h17m18 0h17" stroke="#726550" stroke-width="8" stroke-linecap="round"/></g>')


