def target_picture(key, character):
    return illustration(key).replace('</svg>','<rect x="6" y="6" width="66" height="72" rx="10" fill="#fff9df"/><text x="39" y="60" text-anchor="middle" font-size="50" font-family="STHeiti,serif" fill="#33594e">'+escape(character)+'</text></svg>')


